#!/usr/bin/env pwsh
$ErrorActionPreference = "Stop"

$RepoRoot = Split-Path -Parent $MyInvocation.MyCommand.Path

Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "  HIGH-TRUST VERIFICATION GATE (BE + FE + CONTRACTS)" -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan

# 0. Guard against tracked generated artifacts, hand-edited auto-generated files, or lockfile drift
Write-Host "`n[0/5] Checking Auto-Generated Files & Forbidden Artifacts Hygiene..." -ForegroundColor Yellow
Push-Location $RepoRoot
try {
    $trackedFiles = git ls-files
    $forbiddenTracked = $trackedFiles | Where-Object {
        $_ -match '(^|/)(bin|obj|node_modules|\.next|out|dist)/' -or
        $_ -match '\.csproj\.user$' -or
        $_ -match '\.tsbuildinfo$' -or
        $_ -match '(^|/)\.env(\.local)?$'
    }
    if ($forbiddenTracked) {
        throw "Forbidden generated or secret files are tracked by Git:`n$($forbiddenTracked -join "`n")"
    }

    # Check if next-env.d.ts or EF migration Designer/Snapshot files were hand-edited without header or accompanying migration
    $dirtyFiles = @(git diff --name-only) + @(git diff --cached --name-only) | Select-Object -Unique
    if ($dirtyFiles -contains "FE/next-env.d.ts") {
        throw "FE/next-env.d.ts is auto-generated by Next.js and must not be modified manually (FE.md)."
    }

    # If package-lock.json is modified, package.json must also be modified
    if (($dirtyFiles -contains "FE/package-lock.json") -and -not ($dirtyFiles -contains "FE/package.json")) {
        throw "FE/package-lock.json was modified without a corresponding dependency change in FE/package.json (FE.md)."
    }

    # Ensure all EF Core auto-generated migration files preserve their // <auto-generated /> header
    $autoGenFiles = Get-ChildItem -Path "BE" -Recurse -File | Where-Object {
        $_.Name -like "*.Designer.cs" -or $_.Name -eq "ApplicationDbContextModelSnapshot.cs"
    }
    foreach ($file in $autoGenFiles) {
        $firstLine = Get-Content -Path $file.FullName -TotalCount 1
        if ($firstLine -notmatch '^//\s*<auto-generated\s*/>') {
            throw "Auto-generated EF Core file '$($file.FullName)' was hand-edited or lost its '// <auto-generated />' header (BE.md)."
        }
    }
}
finally {
    Pop-Location
}

# 1. Backend Verification
Write-Host "`n[1/5] Building Backend (Release + Roslyn Analyzers + .editorconfig)..." -ForegroundColor Yellow
Push-Location (Join-Path $RepoRoot "BE")
try {
    dotnet build Boilerplate.slnx --configuration Release
    if ($LASTEXITCODE -ne 0) { throw "Backend Release build failed." }

    Write-Host "`n[2/5] Running Backend Architecture, Contract & Auth Workflow Tests..." -ForegroundColor Yellow
    dotnet test Boilerplate.Tests/Boilerplate.Tests.csproj --configuration Release --no-build --verbosity normal
    if ($LASTEXITCODE -ne 0) { throw "Backend tests failed." }
}
finally {
    Pop-Location
}

# 2. Frontend Verification
Push-Location (Join-Path $RepoRoot "FE")
try {
    Write-Host "`n[3/5] Running Frontend ESLint (Architectural Boundaries & Import Rules)..." -ForegroundColor Yellow
    npm run lint
    if ($LASTEXITCODE -ne 0) { throw "Frontend lint failed." }

    Write-Host "`n[4/5] Running Frontend TypeScript Strict Typecheck..." -ForegroundColor Yellow
    npm run typecheck
    if ($LASTEXITCODE -ne 0) { throw "Frontend typecheck failed." }

    Write-Host "`n[5/5] Running Frontend Runtime Guard & API Contract Tests..." -ForegroundColor Yellow
    npm test
    if ($LASTEXITCODE -ne 0) { throw "Frontend tests failed." }
}
finally {
    Pop-Location
}

Write-Host "`n==========================================================" -ForegroundColor Green
Write-Host "  ALL HIGH-TRUST CHECKS PASSED SUCCESSFULLY!" -ForegroundColor Green
Write-Host "==========================================================" -ForegroundColor Green
